package com.fromscratch.persistence;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.bank.*;
import com.fromscratch.buyback.*;
import com.fromscratch.pouch.*;
import com.google.gson.*;
import java.io.IOException;
import java.util.*;
import java.util.stream.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Filepath;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/** Genuine pre-safeguard format-8 history, byte archives and interrupted adjustment publication. */
public class PouchPersistenceTest
{
	@Rule public TemporaryFolder temporary=new TemporaryFolder();
	private Filepath root,d,current;private BankRunCodec codec;private BankRepository repository;
	@Before public void setup(){root=Filepath.Unchecked.getRooted(temporary.getRoot().toPath());d=root.join("characters",SnapshotFixtures.CHARACTER_A);current=d.joinSegment("current.json");codec=new BankRunCodec(SnapshotFixtures.gson());repository=new BankRepository(codec,SnapshotFixtures.codec());}
	private BankRun initial()throws Exception{BankRun a=BankEngine.start(SnapshotFixtures.CHARACTER_A,null,BuybackModelTest.bank(ItemID.BH_RUNE_POUCH),true,UUID.randomUUID(),SnapshotFixtures.TIME);repository.save(root,null,a);Map<Integer,Long> q=new TreeMap<>(a.getPhysical());q.put(ItemID.COINS,2000000L);return repository.save(root,a,BankEngine.observe(a,new com.fromscratch.model.ContainerSnapshot(q,2),UUID.randomUUID(),SnapshotFixtures.TIME));}
	private BankRun load()throws Exception{return repository.load(root,SnapshotFixtures.CHARACTER_A).get();}
	private Map<String,String> format8(boolean purchased)throws Exception
	{
		BankRun before=initial();
		if(purchased)
		{
			// Historical writer fixture: M7 had no contents review. Never a production bypass.
			BankRun paid=BuybackModelTest.buy(BuybackModelTest.emptyPouch(before),"rune_pouch_family");BuybackPurchase p=paid.getBuybacks().getPurchases().get(0);BuybackPurchase oldPayment=new BuybackPurchase(p.getId(),p.getCatalogId(),p.getGp(),p.getAt(),p.getBankFloors());BankAudit audit=new BankAudit(p.getId(),UUID.randomUUID(),p.getAt(),BankAudit.Kind.BUYBACK,Collections.emptyMap(),Collections.emptyMap(),"Historical M7 purchase.",Collections.emptyList(),com.fromscratch.ge.GeUpdate.empty(),oldPayment);List<BankAudit> recent=new ArrayList<>(before.getRecent());recent.add(0,audit);
			BankRun historical=new BankRun(before.getCharacter(),before.getRunId(),before.getPreviousRunId(),before.getStartedAt(),audit.getId(),before.getSequence()+1,before.getInitialBank(),before.getPhysical(),before.getBalances(),true,before.getLegacyDocument(),before.getMigrationArchive(),recent,before.getHostSummary(),before.getFinancial(),before.getExchange(),new BuybackState(paid.getBuybacks().getCatalogVersion(),paid.getBuybacks().getEntitlements(),paid.getBuybacks().getBankFloors(),paid.getBuybacks().getCommittedGp(),Collections.singletonList(oldPayment),paid.getBuybacks().getArchive(),PouchState.unreviewed()));
			String encoded=codec.encode(historical);d.joinSegment("bank-checkpoint-"+historical.getRevision()+".json").write(encoded);current.write(encoded);
			JsonObject batch=new JsonObject();batch.addProperty("character",before.getCharacter());batch.addProperty("run",before.getRunId().toString());batch.addProperty("previous",before.getRevision().toString());batch.addProperty("sequence",historical.getSequence());batch.addProperty("result",SaveIntegrity.sha256(encoded));batch.add("audit",codec.audit(audit));d.joinSegment("bank-ledger-"+historical.getRevision()+".json").write(codec.envelope(batch,1));
		}
		List<Filepath> files;try(Stream<Filepath> walk=d.walk(1)){files=walk.filter(f->f.getFileName().endsWith(".json")).collect(Collectors.toList());}
		for(Filepath file:files){if(!file.getFileName().startsWith("bank-ledger-")){JsonObject p=codec.payload(BankStorageFiles.readText(file),BankRunCodec.FORMAT);p.remove("potions");p.getAsJsonObject("buybacks").remove("pouch");file.write(codec.envelope(p,8));}}
		for(Filepath file:files){if(file.getFileName().startsWith("bank-ledger-")){JsonObject p=codec.payload(BankStorageFiles.readText(file),1);String id=file.getFileName().substring(12,file.getFileName().length()-5);p.addProperty("result",SaveIntegrity.sha256(BankStorageFiles.readText(d.joinSegment("bank-checkpoint-"+id+".json"))));file.write(codec.envelope(p,1));}}
		Map<String,String> originals=new TreeMap<>();for(Filepath f:files){originals.put(f.getFileName(),BankStorageFiles.readText(f));}return originals;
	}
	@Test public void existingPaidPouchMigratesWithOnePaymentNoRuneDebitsAndNoRevocation()throws Exception{Map<String,String> originals=format8(true);BankRun old=codec.decode(originals.get("current.json"),SnapshotFixtures.CHARACTER_A),next=load();assertEquals(old.getRunId(),next.getRunId());assertEquals(old.getStartedAt(),next.getStartedAt());assertEquals(old.getInitialBank(),next.getInitialBank());assertEquals(old.getPhysical(),next.getPhysical());assertEquals(old.getBalances(),next.getBalances());assertEquals(old.getFinancial(),next.getFinancial());assertEquals(old.getExchange(),next.getExchange());assertEquals(old.getBuybacks().getPurchases(),next.getBuybacks().getPurchases());assertEquals(1000000,next.getBuybacks().getCommittedGp());assertEquals(PouchState.Phase.UNREVIEWED,next.getBuybacks().getPouch().getPhase());assertTrue(next.getBuybacks().getPouch().getRecorded().isEmpty());assertEquals(Long.valueOf(1),BuybackEngine.balances(next).get(ItemID.BH_RUNE_POUCH));assertEquals(BankAudit.Kind.POUCH_BASELINE,next.getRecent().get(0).getKind());}
	@Test public void everyOldCheckpointAndLedgerByteIsArchivedBeforeMigration()throws Exception{Map<String,String> originals=format8(true);BankRun next=load();for(Map.Entry<String,String> e:originals.entrySet()){assertEquals(e.getValue(),BankStorageFiles.readText(d.join(next.getBuybacks().getPouch().getArchive(),e.getKey())));}assertEquals(next,load());}
	@Test public void oldPaidPouchNeedsNoReviewAndNeverChargesAgain()throws Exception{format8(true);BankRun ready=load();assertEquals(1000000,ready.getBuybacks().getCommittedGp());assertEquals(1,ready.getBuybacks().getPurchases().size());try{BuybackModelTest.buy(ready,"rune_pouch_family");fail();}catch(IllegalArgumentException expected){}assertEquals(ready,load());}
	@Test public void unpurchasedOldRunMigratesWithoutChangingBalances()throws Exception{Map<String,String> old=format8(false);BankRun next=load();assertEquals(codec.decode(old.get("current.json"),SnapshotFixtures.CHARACTER_A).getBalances(),next.getBalances());assertEquals(0,next.getBuybacks().getCommittedGp());assertEquals(PouchState.Phase.UNREVIEWED,next.getBuybacks().getPouch().getPhase());}
	@Test public void interruptedMigrationRetainsOriginalCurrentAndCanRetry()throws Exception{Map<String,String> old=format8(true);BankRepository failed=new BankRepository(codec,SnapshotFixtures.codec(),(a,b)->{throw new IOException("interrupted");});try{failed.load(root,SnapshotFixtures.CHARACTER_A);fail();}catch(SaveException expected){}assertEquals(old.get("current.json"),BankStorageFiles.readText(current));assertEquals(1000000,load().getBuybacks().getCommittedGp());}
	@Test public void corruptRequiredPouchStateCannotResetValidProgress()throws Exception{BankRun old=initial();String good=BankStorageFiles.readText(current);JsonObject p=codec.payload(good,BankRunCodec.FORMAT);p.getAsJsonObject("buybacks").remove("pouch");String bad=codec.envelope(p,BankRunCodec.FORMAT);current.write(bad);try{load();fail();}catch(SaveException expected){}assertEquals(bad,BankStorageFiles.readText(current));assertEquals(old,codec.decode(good,SnapshotFixtures.CHARACTER_A));}
	@Test public void interruptedLegacyAdjustmentDoesNotAdvanceOrReplayTwice()throws Exception{BankRun old=initial();PouchAction action=new PouchAction(PouchAction.Kind.REGISTER,Collections.singletonMap(ItemID.NATURERUNE,500L),false,false,"Player verified contents.");BankRun prepared=repository.save(root,old,BankEngine.pouch(old,action,UUID.randomUUID(),SnapshotFixtures.TIME,Collections.emptyMap()));Map<Integer,Long> bank=new TreeMap<>(prepared.getPhysical());bank.put(ItemID.NATURERUNE,500L);BankRun next=BankEngine.observe(prepared,new com.fromscratch.model.ContainerSnapshot(bank,3),UUID.randomUUID(),SnapshotFixtures.TIME);BankRepository failed=new BankRepository(codec,SnapshotFixtures.codec(),(a,b)->{throw new IOException("interrupted");});try{failed.save(root,prepared,next);fail();}catch(SaveException expected){}assertEquals(prepared,load());assertEquals(next,repository.save(root,prepared,next));assertEquals(next,repository.save(root,prepared,next));assertEquals(0,load().balance(ItemID.NATURERUNE));assertEquals(Long.valueOf(500),load().getBuybacks().getPouch().getHeld().get(ItemID.NATURERUNE));}
	@Test public void damagedPouchMigrationArchiveBlocksLoadAndPreservesCurrent()throws Exception{format8(true);BankRun next=load();String before=BankStorageFiles.readText(current);d.join(next.getBuybacks().getPouch().getArchive(),"current.json").write("damaged");try{load();fail();}catch(SaveException expected){}assertEquals(before,BankStorageFiles.readText(current));}
	@Test public void automaticPurchaseDebitAndEntitlementRecoverAsOneCommit()throws Exception{BankRun before=initial();PouchObservation contents=new PouchObservation(true,Collections.singletonMap(ItemID.NATURERUNE,500L),SnapshotFixtures.TIME,ItemID.BH_RUNE_POUCH);BankRun next=BankEngine.buyback(before,"rune_pouch_family",UUID.randomUUID(),UUID.randomUUID(),SnapshotFixtures.TIME,contents);BankRepository failed=new BankRepository(codec,SnapshotFixtures.codec(),(a,b)->{throw new IOException("interrupted");});try{failed.save(root,before,next);fail();}catch(SaveException expected){}assertEquals(before,load());repository.save(root,before,next);assertEquals(next,repository.save(root,before,next));assertEquals(-500,load().balance(ItemID.NATURERUNE));assertEquals(1000000,load().getBuybacks().getCommittedGp());assertEquals(Long.valueOf(500),load().getBuybacks().getPurchases().get(0).getLegacyRunes().get(ItemID.NATURERUNE));}
	@Test public void oldPendingContentsOutsidePouchStayProtectedWithoutDuplicatingOverlappingDebit()throws Exception{BankRun old=initial();Map<Integer,Long> recorded=new TreeMap<>();recorded.put(ItemID.NATURERUNE,500L);recorded.put(ItemID.LAWRUNE,200L);BankRun prepared=repository.save(root,old,BankEngine.pouch(old,new PouchAction(PouchAction.Kind.REGISTER,recorded,false,false,"Historical verified contents."),UUID.randomUUID(),SnapshotFixtures.TIME,Collections.emptyMap()));BankRun purchased=repository.save(root,prepared,BankEngine.buyback(prepared,"rune_pouch_family",UUID.randomUUID(),UUID.randomUUID(),SnapshotFixtures.TIME,new PouchObservation(true,Collections.singletonMap(ItemID.NATURERUNE,500L),SnapshotFixtures.TIME,ItemID.BH_RUNE_POUCH)));assertEquals(-500,purchased.balance(ItemID.NATURERUNE));assertEquals(Collections.singletonMap(ItemID.LAWRUNE,200L),purchased.getBuybacks().getPouch().getRemaining());Map<Integer,Long> bank=new TreeMap<>(purchased.getPhysical());bank.putAll(recorded);BankRun deposited=repository.save(root,purchased,BankEngine.observe(purchased,new com.fromscratch.model.ContainerSnapshot(bank,4),UUID.randomUUID(),SnapshotFixtures.TIME));assertEquals(0,deposited.balance(ItemID.NATURERUNE));assertEquals(0,deposited.balance(ItemID.LAWRUNE));assertEquals(old.getFinancial(),deposited.getFinancial());}
}
